// ClassroomTwin - self-test. Expected values were generated by the independent Python reference
// model (ref/model.py) used to write the specification. Run from Unity menu: Digital Twin > Run Self-Test.
// Every line must print PASS. Tolerance: 1e-6 absolute (1e-4 for 24-h energy sums).
using System;
using System.Collections.Generic;

namespace ClassroomTwin.Core
{
    public static class TwinSelfTest
    {
        public static int Failures;

        static void Check(List<string> log, string name, double got, double expected)
        {
            double tol = name.StartsWith("Day_") ? 1e-4 : 1e-6;
            bool ok = (double.IsNaN(expected) && double.IsNaN(got)) || Math.Abs(got - expected) <= tol;
            if (!ok) Failures++;
            log.Add((ok ? "PASS " : "FAIL ") + name + "  got=" + got.ToString("R") + "  expected=" + expected.ToString("R"));
        }

        public static List<string> Run()
        {
            Failures = 0;
            List<string> log = new List<string>();
            MamdaniFIS lightPaper = TwinControllers.BuildLightFis(true);
            MamdaniFIS lightClass = TwinControllers.BuildLightFis(false);
            MamdaniFIS curtain = TwinControllers.BuildCurtainFis(false, true);
            DayResult[,] days = TwinSimulator.RunAll();
            Check(log, "MF_Light_Low_0", TwinControllers.LightInput().Sets[0].Mu(0), 1.0);
            Check(log, "MF_Light_Low_25", TwinControllers.LightInput().Sets[0].Mu(25), 1.0);
            Check(log, "MF_Light_Low_35", TwinControllers.LightInput().Sets[0].Mu(35), 0.5);
            Check(log, "MF_Light_Low_45", TwinControllers.LightInput().Sets[0].Mu(45), 0.0);
            Check(log, "MF_Light_Medium_45", TwinControllers.LightInput().Sets[1].Mu(45), 0.5);
            Check(log, "MF_Light_Medium_55", TwinControllers.LightInput().Sets[1].Mu(55), 1.0);
            Check(log, "MF_Light_High_70", TwinControllers.LightInput().Sets[2].Mu(70), 0.5);
            Check(log, "MF_Light_High_100", TwinControllers.LightInput().Sets[2].Mu(100), 1.0);
            Check(log, "Tau_0", TwinSimulator.Tau(0), 1.0);
            Check(log, "Tau_25", TwinSimulator.Tau(25), 0.5734196920554815);
            Check(log, "Tau_45", TwinSimulator.Tau(45), 0.28626409273982867);
            Check(log, "Tau_75", TwinSimulator.Tau(75), 0.050000000000000044);
            Check(log, "ToutNormal_3", TwinSimulator.Tout(3, TwinConfig.Profile(Weather.Normal)), 20.0);
            Check(log, "ToutNormal_9", TwinSimulator.Tout(9, TwinConfig.Profile(Weather.Normal)), 24.0);
            Check(log, "ToutNormal_15", TwinSimulator.Tout(15, TwinConfig.Profile(Weather.Normal)), 28.0);
            Check(log, "Sun_6", TwinSimulator.Sun(6), 0.0);
            Check(log, "Sun_9", TwinSimulator.Sun(9), 0.7071067811865475);
            Check(log, "Sun_12", TwinSimulator.Sun(12), 1.0);
            Check(log, "LightFisPaper_4_19_30", lightPaper.Evaluate(new double[] { 4, 19, 30 }, null), 27.727272727272798);
            Check(log, "LightFisPaper_9_11_18", lightPaper.Evaluate(new double[] { 9, 11, 18 }, null), 59.99999999999986);
            Check(log, "LightFisPaper_20_12_22", lightPaper.Evaluate(new double[] { 20, 12, 22 }, null), 50.0);
            Check(log, "LightFisPaper_30_19_34", lightPaper.Evaluate(new double[] { 30, 19, 34 }, null), 27.727272727272798);
            Check(log, "LightFisPaper_45_4_23", lightPaper.Evaluate(new double[] { 45, 4, 23 }, null), 19.999999999999996);
            Check(log, "LightFisPaper_65_10_25", lightPaper.Evaluate(new double[] { 65, 10, 25 }, null), 53.56643356643342);
            Check(log, "LightFisPaper_87_14_30", lightPaper.Evaluate(new double[] { 87, 14, 30 }, null), 20.000000000000004);
            Check(log, "LightFisClass_10_12_26", lightClass.Evaluate(new double[] { 10, 12, 26 }, null), 49.99999999999996);
            Check(log, "LightFisClass_40_11_27", lightClass.Evaluate(new double[] { 40, 11, 27 }, null), 64.99999999999999);
            Check(log, "LightFisClass_90_12_29", lightClass.Evaluate(new double[] { 90, 12, 29 }, null), 20.000000000000007);
            Check(log, "LightFisClass_100_12_42", lightClass.Evaluate(new double[] { 100, 12, 42 }, null), 20.000000000000004);
