            Check(log, "CurtainFis_10_25_300_12_0", curtain.Evaluate(new double[] { 10, 25, 300, 12, 0 }, null), double.NaN);
            Check(log, "CurtainFis_70_23_60_9_75", curtain.Evaluate(new double[] { 70, 23, 60, 9, 75 }, null), 25.833333333333332);
            Check(log, "Day_Normal_S0_LightingKWh", days[0, 0].LightingKWh, 18.72);
            Check(log, "Day_Normal_S0_CoolingKWh", days[0, 0].CoolingKWh, 9.612414889571395);
