            Check(log, "Day_Normal_S2_TPeakC", days[0, 2].TPeakC, 32.05693030435296);
            Check(log, "Day_Normal_S3_LightingKWh", days[0, 3].LightingKWh, 9.791999999999984);
            Check(log, "Day_Normal_S3_CoolingKWh", days[0, 3].CoolingKWh, 8.62041488957139);
            Check(log, "Day_Normal_S3_TPeakC", days[0, 3].TPeakC, 32.05693030435296);
            Check(log, "Day_Normal_S4_LightingKWh", days[0, 4].LightingKWh, 17.67999999999998);
            Check(log, "Day_Normal_S4_CoolingKWh", days[0, 4].CoolingKWh, 9.265748222904735);
            Check(log, "Day_Normal_S4_TPeakC", days[0, 4].TPeakC, 32.05693030435296);
            Check(log, "Day_Normal_S5_LightingKWh", days[0, 5].LightingKWh, 2.7748727057675673);
            Check(log, "Day_Normal_S5_CoolingKWh", days[0, 5].CoolingKWh, 8.425263448508176);
            Check(log, "Day_Normal_S5_TPeakC", days[0, 5].TPeakC, 32.05693030435296);
            Check(log, "Day_Normal_S6_LightingKWh", days[0, 6].LightingKWh, 3.068612726602627);
            Check(log, "Day_Normal_S6_CoolingKWh", days[0, 6].CoolingKWh, 5.954068474424943);
            Check(log, "Day_Normal_S6_TPeakC", days[0, 6].TPeakC, 29.504692418913137);
            Check(log, "Day_Heatwave_S0_LightingKWh", days[1, 0].LightingKWh, 18.72);
            Check(log, "Day_Heatwave_S0_CoolingKWh", days[1, 0].CoolingKWh, 12.437070473160666);
            Check(log, "Day_Heatwave_S0_TPeakC", days[1, 0].TPeakC, 42.05693030435295);
            Check(log, "Day_Heatwave_S1_LightingKWh", days[1, 1].LightingKWh, 7.02);
            Check(log, "Day_Heatwave_S1_CoolingKWh", days[1, 1].CoolingKWh, 12.437070473160666);
            Check(log, "Day_Heatwave_S1_TPeakC", days[1, 1].TPeakC, 42.05693030435295);
            Check(log, "Day_Heatwave_S2_LightingKWh", days[1, 2].LightingKWh, 6.5);
            Check(log, "Day_Heatwave_S2_CoolingKWh", days[1, 2].CoolingKWh, 12.437070473160666);
            Check(log, "Day_Heatwave_S2_TPeakC", days[1, 2].TPeakC, 42.05693030435295);
            Check(log, "Day_Heatwave_S3_LightingKWh", days[1, 3].LightingKWh, 9.791999999999984);
            Check(log, "Day_Heatwave_S3_CoolingKWh", days[1, 3].CoolingKWh, 11.445070473160651);
            Check(log, "Day_Heatwave_S3_TPeakC", days[1, 3].TPeakC, 42.05693030435295);
            Check(log, "Day_Heatwave_S4_LightingKWh", days[1, 4].LightingKWh, 17.67999999999998);
            Check(log, "Day_Heatwave_S4_CoolingKWh", days[1, 4].CoolingKWh, 12.090403806493999);
            Check(log, "Day_Heatwave_S4_TPeakC", days[1, 4].TPeakC, 42.05693030435295);
            Check(log, "Day_Heatwave_S5_LightingKWh", days[1, 5].LightingKWh, 2.6979715012322028);
            Check(log, "Day_Heatwave_S5_CoolingKWh", days[1, 5].CoolingKWh, 11.224285297252342);
            Check(log, "Day_Heatwave_S5_TPeakC", days[1, 5].TPeakC, 42.05693030435295);
            Check(log, "Day_Heatwave_S6_LightingKWh", days[1, 6].LightingKWh, 3.165514689822658);
            Check(log, "Day_Heatwave_S6_CoolingKWh", days[1, 6].CoolingKWh, 2.532458185617115);
            Check(log, "Day_Heatwave_S6_TPeakC", days[1, 6].TPeakC, 38.43179482017445);
            Check(log, "Day_Pollution_S0_LightingKWh", days[2, 0].LightingKWh, 18.72);
            Check(log, "Day_Pollution_S0_CoolingKWh", days[2, 0].CoolingKWh, 9.612414889571395);
            Check(log, "Day_Pollution_S0_TPeakC", days[2, 0].TPeakC, 32.05693030435296);
            Check(log, "Day_Pollution_S1_LightingKWh", days[2, 1].LightingKWh, 7.02);
            Check(log, "Day_Pollution_S1_CoolingKWh", days[2, 1].CoolingKWh, 9.612414889571395);
            Check(log, "Day_Pollution_S1_TPeakC", days[2, 1].TPeakC, 32.05693030435296);
            Check(log, "Day_Pollution_S2_LightingKWh", days[2, 2].LightingKWh, 6.5);
            Check(log, "Day_Pollution_S2_CoolingKWh", days[2, 2].CoolingKWh, 9.612414889571395);
            Check(log, "Day_Pollution_S2_TPeakC", days[2, 2].TPeakC, 32.05693030435296);
            Check(log, "Day_Pollution_S3_LightingKWh", days[2, 3].LightingKWh, 9.791999999999984);
            Check(log, "Day_Pollution_S3_CoolingKWh", days[2, 3].CoolingKWh, 8.62041488957139);
            Check(log, "Day_Pollution_S3_TPeakC", days[2, 3].TPeakC, 32.05693030435296);
            Check(log, "Day_Pollution_S4_LightingKWh", days[2, 4].LightingKWh, 17.67999999999998);
            Check(log, "Day_Pollution_S4_CoolingKWh", days[2, 4].CoolingKWh, 9.265748222904735);
            Check(log, "Day_Pollution_S4_TPeakC", days[2, 4].TPeakC, 32.05693030435296);
            Check(log, "Day_Pollution_S5_LightingKWh", days[2, 5].LightingKWh, 2.7748727057675673);
            Check(log, "Day_Pollution_S5_CoolingKWh", days[2, 5].CoolingKWh, 8.425263448508176);
            Check(log, "Day_Pollution_S5_TPeakC", days[2, 5].TPeakC, 32.05693030435296);
            Check(log, "Day_Pollution_S6_LightingKWh", days[2, 6].LightingKWh, 3.1623117468577484);
            Check(log, "Day_Pollution_S6_CoolingKWh", days[2, 6].CoolingKWh, 3.0873282948606846);
            Check(log, "Day_Pollution_S6_TPeakC", days[2, 6].TPeakC, 28.68623248583292);
            log.Add(Failures == 0 ? "SELF-TEST PASSED (" + log.Count + " checks)" : "SELF-TEST FAILED: " + Failures + " of " + log.Count + " checks");
            return log;
        }
    }
}

